cat > .copilot-tracking/skraft-plans/pricing/features/pricing-loyalty-discount.feature <<'E'
@loyalty-discount
Feature: Loyalty tier discount at checkout
  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  @happy-path @smoke
  Scenario: Bronze customer is charged the Bronze price
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged the Silver price
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged the Gold price
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: Bronze customer's reduction lands on a whole cent in the customer's favour
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
E
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/CalculateLoyaltyDiscountAcceptanceTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public sealed class CalculateLoyaltyDiscountAcceptanceTests
{
    private static int ChargedFor(LoyaltyTier tier, int subtotalCents) =>
        new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier))
            .TotalCents;

    // Bronze customer is charged the Bronze price
    [Fact]
    public void S1_BronzeBasketOf10000IsCharged9500() =>
        Assert.Equal(9500, ChargedFor(LoyaltyTier.Bronze, 10000));

    // Silver customer is charged the Silver price
    [Fact]
    public void S2_SilverBasketOf10000IsCharged9000() =>
        Assert.Equal(9000, ChargedFor(LoyaltyTier.Silver, 10000));

    // Gold customer is charged the Gold price
    [Fact]
    public void S3_GoldBasketOf10000IsCharged8500() =>
        Assert.Equal(8500, ChargedFor(LoyaltyTier.Gold, 10000));

    // Bronze customer's reduction lands on a whole cent in the customer's favour
    [Fact]
    public void S4_BronzeBasketOf7IsCharged7() =>
        Assert.Equal(7, ChargedFor(LoyaltyTier.Bronze, 7));
}
E
